 raceT=0;falls=0;cd=3.4;goT=0;msgT=0;state="countdown";rec=[];recT=0;gi=0;gd=0;sec=newSec();secLog=[];spray=[];skids=[];spl=[];lastSk=null;inCrowd=false;
